<script>
import Icon from './Icon.svelte';
import {flip} from 'svelte/animate';
import {onMount} from 'svelte';
import {decodeStages,encodeStages,rampPoints,stageRates} from './ramp-editor.mjs';
import {loadShape} from './load-shape.mjs';
export let startRps=0;export let stagesJson='[]';export let valid=true;export let targets=[];
let sequence=0;
const identify=row=>row._uiId?row:{...row,_uiId:`stage-${++sequence}`};
let rows;try{rows=decodeStages(stagesJson,startRps).map(identify);}catch{rows=[];}
let validation='',advanced='',importMessage='',dragged='',dragPointer=null,editor,dragBefore=null,undo=null,lastPointer=null,selectedStage='',editingStage='',dragCandidate=null,suppressStageClick=false,plotWidth=800;
const durationLabel=value=>{const seconds=Number(value)||0;if(seconds<60)return `${seconds} sec`;const minutes=seconds/60;return `${Number.isInteger(minutes)?minutes:Number(minutes.toFixed(1))} ${minutes===1?'min':'mins'}`;};
$: starts=rows.map((_,i)=>rows.slice(0,i).reduce((n,row)=>n+Number(row.duration||0),0));
function sync(){try{for(const row of rows){if(row.kind==='fault'){const actions=targets.find(target=>target.id===row.fault?.targetId)?.actions;if(actions?.length===1)row.fault.action=actions[0];}}stagesJson=JSON.stringify(encodeStages(rows,startRps));validation='';valid=true;}catch(e){validation=e.message;valid=false;}}
function move(i,offset){undo=structuredClone(rows);const next=[...rows];[next[i],next[i+offset]]=[next[i+offset],next[i]];rows=next;sync();}
function add(kind){rows=[...rows,identify({kind,target:stageRates(rows,startRps).at(-1) ?? Number(startRps),duration:kind==='fault'?10:60,...(kind==='fault'?{fault:{targetId:targets[0]?.id||'',action:targets[0]?.actions[0]||'outage'}}:{})})];editingStage=rows.at(-1)._uiId;sync();}
function dragStart(event,id){if(event.button!==0&&!(event.buttons&1))return;event.preventDefault();selectedStage=id;dragBefore=structuredClone(rows);dragged=id;dragPointer=event.pointerId;lastPointer={clientY:event.clientY,pointerId:event.pointerId,preventDefault:()=>{}};}
function dragMove(event){if(dragCandidate&&event.pointerId===dragCandidate.pointerId&&Math.hypot(event.clientX-dragCandidate.x,event.clientY-dragCandidate.y)>6){const id=dragCandidate.id;dragCandidate=null;dragStart(event,id);suppressStageClick=true;}if(!dragged||event.pointerId!==dragPointer||!editor)return;event.preventDefault();lastPointer={clientY:event.clientY,pointerId:event.pointerId,preventDefault:()=>{}};const current=rows.findIndex(row=>row._uiId===dragged);const elements=[...editor.querySelectorAll('[data-stage-id]')];const target=elements.findIndex(element=>event.clientY<element.getBoundingClientRect().top+element.getBoundingClientRect().height/2);const insertion=target<0?rows.length:target,destination=Math.max(0,Math.min(rows.length-1,insertion-(current<insertion?1:0)));if(current<0||destination===current)return;const next=[...rows],item=next.splice(current,1)[0];next.splice(destination,0,item);rows=next;sync();}
function dragEnd(event){dragCandidate=null;if(event?.pointerId!==undefined&&event.pointerId!==dragPointer)return;if(dragBefore)undo=dragBefore;dragBefore=null;dragged='';dragPointer=null;lastPointer=null;}
function cancelDrag(event){if(event.key==='Escape'&&dragged){rows=dragBefore;dragBefore=null;dragEnd();sync();}}
function prepareStageDrag(event,id){suppressStageClick=false;if(event.button===0)dragCandidate={id,x:event.clientX,y:event.clientY,pointerId:event.pointerId};}
function toggleStage(id){if(suppressStageClick){suppressStageClick=false;return;}editingStage=editingStage===id?'':id;}
function rowDrag(event,id){if(!event.target.closest('input,select,button,summary,a,label,details'))dragStart(event,id);}
function keyboardMove(event,index){if(!event.altKey||!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const offset=event.key==='ArrowUp'?-1:1;if(index+offset>=0&&index+offset<rows.length)move(index,offset);}
function importJson(){try{rows=decodeStages(advanced,startRps).map(identify);sync();if(validation)throw Error(validation);importMessage='Imported';}catch(e){validation=e.message;}}
onMount(()=>{const observer=new ResizeObserver(entries=>plotWidth=Math.max(280,entries[0].contentRect.width));observer.observe(editor);const autoScroll=setInterval(()=>{if(!dragged||!lastPointer)return;const y=lastPointer.clientY,delta=y<155?-12:y>window.innerHeight-70?12:0;if(delta){window.scrollBy(0,delta);dragMove(lastPointer);}},16);window.addEventListener('keydown',cancelDrag);window.addEventListener('pointermove',dragMove,{passive:false});window.addEventListener('pointerup',dragEnd);window.addEventListener('pointercancel',dragEnd);window.addEventListener('blur',dragEnd);return()=>{observer.disconnect();clearInterval(autoScroll);window.removeEventListener('keydown',cancelDrag);window.removeEventListener('pointermove',dragMove);window.removeEventListener('pointerup',dragEnd);window.removeEventListener('pointercancel',dragEnd);window.removeEventListener('blur',dragEnd);};});
$: startRps,targets,sync();
$: rates=stageRates(rows,startRps);
$: points=(()=>{try{return rampPoints(startRps,JSON.parse(stagesJson));}catch{return [];}})();
$: shape=(()=>{try{return loadShape({start_rps:startRps,stages:JSON.parse(stagesJson)});}catch{return {duration:0,peak:0,average:0};}})();
$: plotSpan=plotWidth-60;
$: line=points.map(p=>`${30+(p.t/(shape.duration||1))*plotSpan},${130-(p.value/(shape.peak||1))*105}`).join(' ');
</script>
<section class="ramp-editor" bind:this={editor}>
<div class="section-head"><div><h2>Timeline</h2><p>Offered flows per second · {shape.duration}s total · {shape.peak} TPS peak</p></div><label>Starting TPS<input type="number" min="0" bind:value={startRps}/></label></div>
<svg viewBox={`0 0 ${plotWidth} 160`} role="img" aria-label="Offered TPS over active test time">{#each rows as row,i}{#if selectedStage===row._uiId}<rect x={30+starts[i]/(shape.duration||1)*plotSpan} y="20" width={Number(row.duration||0)/(shape.duration||1)*plotSpan} height="110" fill="#0561e212"/>{/if}{/each}<path d={`M30 20V130H${plotWidth-30}`} fill="none" stroke="#dfe3eb"/>{#each rows as row,i}{#if row.kind==='fault'}<line x1={30+(rows.slice(0,i).reduce((n,r)=>n+Number(r.duration),0)/(shape.duration||1))*plotSpan} x2={30+(rows.slice(0,i).reduce((n,r)=>n+Number(r.duration),0)/(shape.duration||1))*plotSpan} y1="20" y2="130" stroke="#bd5a20" stroke-dasharray="4 4"/>{/if}{/each}<polyline points={line} fill="none" stroke="#0066ff" stroke-width="2.5"/>{#each points as point}<circle cx={30+(point.t/(shape.duration||1))*plotSpan} cy={130-(point.value/(shape.peak||1))*105} r="3" fill="#0066ff"/>{/each}<text x="30" y="153">0s</text><text x={plotWidth-30} y="153" text-anchor="end">{shape.duration}s</text><text x="35" y="18">{shape.peak} TPS</text></svg>
<div class="stage-list">
{#each rows as row,i (row._uiId)}
  <div animate:flip={{duration:180}} data-stage-id={row._uiId} role="group" aria-label={`Stage ${i+1}`} class="stage-row" onfocusin={()=>selectedStage=row._uiId} onpointerenter={()=>selectedStage=row._uiId} onpointerdown={event=>rowDrag(event,row._uiId)} class:expanded={editingStage===row._uiId} class:dragging={dragged===row._uiId}>
    <button type="button" class="quiet drag-handle" aria-label={`Move stage ${i+1}. Drag or press Alt plus arrow keys.`} aria-pressed={dragged===row._uiId} onpointerdown={e=>dragStart(e,row._uiId)} onkeydown={e=>keyboardMove(e,i)}><Icon name="grip"/></button>
    <span class="stage-number" aria-hidden="true">{i+1}</span>
    <button type="button" class="quiet stage-summary" aria-expanded={editingStage===row._uiId} onpointerdown={e=>prepareStageDrag(e,row._uiId)} onclick={()=>toggleStage(row._uiId)}>
      <span class="stage-symbol" class:fault={row.kind==='fault'}><Icon name={row.kind==='fault'?'bolt':row.kind==='ramp'?'performance':'clock'}/></span>
      <span><strong>{row.kind==='fault'?`${targets.find(t=>t.id===row.fault?.targetId)?.label || 'Choose fault target'} ${row.fault?.action==='failover'?'failover':'outage'}`:`${row.kind==='ramp'?'Ramp up to':'Hold'} ${rates[i]} TPS`}</strong><small>{durationLabel(row.duration)}</small></span>
      <span class="edit-cue">{editingStage===row._uiId?'Close':'Edit'}</span>
    </button>
    <div class="row-actions"><button type="button" class="icon-button danger" aria-label={`Remove stage ${i+1}`} onclick={()=>{undo=structuredClone(rows);rows=rows.filter((_,n)=>n!==i);sync();}}><Icon name="close"/></button></div>
    {#if editingStage===row._uiId}<div class="stage-fields">
      <label>Stage<select bind:value={row.kind} onchange={()=>{if(row.kind==='fault')row.fault ||= {targetId:targets[0]?.id||'',action:targets[0]?.actions[0]||'outage'};sync();}}><option value="ramp">Ramp to</option><option value="hold">Hold</option><option value="fault">Fault</option></select></label>
      {#if row.kind==='fault'}<label>Target<select bind:value={row.fault.targetId} onchange={()=>{row.fault.action=targets.find(t=>t.id===row.fault.targetId)?.actions[0]||'outage';sync();}}><option value="">Choose target</option>{#each targets as target}<option value={target.id}>{target.label}</option>{/each}</select></label>
      {:else if row.kind==='ramp'}<label>Target TPS<input type="number" min="1" bind:value={row.target} oninput={sync}/></label>
      {:else}<div class="hold-rate"><span>Hold TPS</span><strong>{rates[i]} TPS</strong><small>From {i===0?'starting TPS':'preceding stage'}</small></div>{/if}
      <label>{row.kind==='fault'?(row.fault.action==='failover'?'Stage duration':'Downtime'):'Duration'} · seconds<input type="number" min="1" max={row.kind==='fault'?300:undefined} step="1" bind:value={row.duration} oninput={sync}/></label>
    </div>{/if}
  </div>
{/each}
</div>
{#if validation}<p class="invalid" role="alert">{validation}</p>{/if}<div class="add-stages" role="group" aria-label="Add timeline stage"><button type="button" class="secondary" onclick={()=>add('ramp')}>+ Ramp</button><button type="button" class="secondary" onclick={()=>add('hold')}>+ Hold</button><button type="button" class="secondary" onclick={()=>add('fault')}>+ Fault</button></div>
{#if undo}<button type="button" class="quiet" onclick={()=>{rows=undo;undo=null;sync();}}>Undo timeline change</button>{/if}<p class="timeline-hint">Faults keep traffic steady and recover automatically.</p>
<details class="advanced"><summary>JSON import / export</summary><label>Current stages<textarea readonly rows="4" value={stagesJson}></textarea></label><label>Import stages<textarea rows="4" bind:value={advanced}></textarea></label><button type="button" class="secondary" onclick={importJson}>Import</button><span role="status">{importMessage}</span></details>
</section>

<style>
.ramp-editor>svg{height:160px}.stage-list{margin-top:16px;border:1px solid var(--border);border-radius:8px;overflow:clip}.stage-row{display:grid;grid-template-columns:28px 24px minmax(0,1fr) auto;gap:10px;padding:10px 12px;border:0;border-bottom:1px solid var(--border);touch-action:pan-y;position:relative;cursor:grab;transition:background-color .14s}.stage-row:last-child{border-bottom:0}.stage-row.expanded{background:#f3f7fc}.stage-row.dragging{background:var(--accent-soft);box-shadow:0 4px 18px #18263b15;z-index:2;outline:1px solid var(--accent);opacity:.75}.drag-handle{width:28px;min-height:32px;padding:0;touch-action:none;user-select:none;cursor:grab}.drag-handle:active,.drag-handle[aria-pressed=true]{cursor:grabbing}.stage-number{align-self:center;color:var(--subtle);font-size:11px;font-weight:500;font-variant-numeric:tabular-nums;text-align:center}.stage-summary{touch-action:pan-y;user-select:none;justify-content:flex-start;text-align:left;padding:6px;min-width:0;white-space:normal}.stage-summary strong{display:block;font-size:12px;font-weight:550;color:var(--ink)}.stage-summary small{display:block;font-size:10px;font-weight:450;margin-top:4px;color:var(--muted)}.stage-symbol{display:flex;align-items:center;justify-content:center;background:var(--accent-soft);color:var(--accent);width:30px;height:30px;border-radius:6px;margin-right:4px;flex-shrink:0}.stage-symbol.fault{background:var(--warning-soft);color:var(--warning)}.edit-cue{margin-left:auto;font-size:11px;color:var(--muted);opacity:0}.stage-summary:hover .edit-cue,.stage-summary:focus-visible .edit-cue,.expanded .edit-cue{opacity:1}.row-actions{display:flex;align-items:center}.stage-fields{grid-column:3/-1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding:8px 6px 12px;cursor:default}.hold-rate{font-size:11px;color:var(--muted)}.hold-rate strong{display:block;color:var(--ink);font-size:13px;margin:8px 0 3px}.hold-rate small{font-size:10px}.add-stages{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.add-stages button{min-height:34px;font-size:12px}.timeline-hint{font-size:11px;color:var(--muted);margin:14px 0 0}.advanced{border:0;border-top:1px solid var(--border);border-radius:0;padding:14px 0 0;margin-top:14px}.advanced label{margin-bottom:14px}.advanced span{font-size:12px;margin-left:10px}
@media(hover:hover){.stage-row:not(.dragging):hover{background:#f7f9fc}.stage-row.expanded:not(.dragging):hover{background:#eef4fb}.stage-row:hover .stage-summary,.stage-row:focus-within .stage-summary{background:transparent;color:inherit;border-color:transparent}}
@media(max-width:650px){.stage-row{grid-template-columns:24px 20px minmax(0,1fr) auto;gap:4px;padding:8px}.stage-symbol{display:none}.stage-fields{grid-column:2/-1;grid-template-columns:1fr}.stage-summary{gap:4px}.edit-cue{display:none}.ramp-editor{padding:14px}.section-head p{max-width:210px}.add-stages{justify-content:stretch}.add-stages button{flex:1;padding-left:8px;padding-right:8px}}
</style>
